"""Generate portable Alfred CSS from assets/tokens.json. Standard library only."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
BRIDGE='/* Tailwind v4 integration fragment, for a standalone Alfred app only.\n   Import after Tailwind, fonts.css and tokens.css in the existing global CSS.\n   For a mixed-brand host, use prefixed tokens.css instead of global font mappings. */\n@theme inline {\n  --font-sans: "Space Grotesk", sans-serif;\n  --font-heading: "Space Grotesk", sans-serif;\n  --font-display: "Archivo Black", sans-serif;\n  --font-mono: "JetBrains Mono", monospace;\n  --color-background: var(--background);\n  --color-foreground: var(--foreground);\n  --color-card: var(--card);\n  --color-card-foreground: var(--card-foreground);\n  --color-popover: var(--popover);\n  --color-popover-foreground: var(--popover-foreground);\n  --color-primary: var(--primary);\n  --color-primary-foreground: var(--primary-foreground);\n  --color-secondary: var(--secondary);\n  --color-secondary-foreground: var(--secondary-foreground);\n  --color-muted: var(--muted);\n  --color-muted-foreground: var(--muted-foreground);\n  --color-accent: var(--accent);\n  --color-accent-foreground: var(--accent-foreground);\n  --color-border: var(--border);\n  --color-input: var(--input);\n  --color-ring: var(--ring);\n  --radius-sm: .25rem;\n  --radius-md: .5rem;\n  --radius-lg: .75rem;\n  --radius-xl: 1.25rem;\n  --radius-2xl: 1.5rem;\n  --radius-4xl: 9999px;\n}\n.alfred-theme {\n  --background: var(--alfred-paper);\n  --foreground: var(--alfred-ink);\n  --card: var(--alfred-white);\n  --card-foreground: var(--alfred-ink);\n  --popover: var(--alfred-white);\n  --popover-foreground: var(--alfred-ink);\n  --primary: var(--alfred-pink);\n  --primary-foreground: var(--alfred-ink);\n  --secondary: var(--alfred-white);\n  --secondary-foreground: var(--alfred-ink);\n  --muted: var(--alfred-paper);\n  --muted-foreground: var(--alfred-muted);\n  --accent: var(--alfred-paper);\n  --accent-foreground: var(--alfred-ink);\n  --border: var(--alfred-ink);\n  --input: var(--alfred-ink);\n  --ring: var(--alfred-blue);\n}\n'
def rem(v):return f'{v/16:g}rem'
def generate():
 t=json.loads((ROOT/'assets/tokens.json').read_text());v=t['version'];defs=[]
 for key,value in t['color'].items():defs.append(f'--alfred-{key}:{value}')
 for key,value in t['font'].items():defs.append(f'--alfred-font-{key}:"{value["family"]}",'+('monospace' if key=='mono' else 'sans-serif'))
 for step,value in t['spacing']['steps'].items():defs.append(f'--alfred-space-{step}:{rem(value)}')
 for key,value in t['spacing']['roles'].items():
  name=''.join('-'+c.lower() if c.isupper() else c for c in key);defs.append(f'--alfred-gap-{name}:{rem(value)}')
 css=f'/* Alfred v{v}. Generated by scripts/build_tokens.py; edit tokens.json. */\n:root{{'+ ';'.join(defs)+'}\n'
 css+='''.alfred-name{font-family:var(--alfred-font-display);font-weight:400;letter-spacing:-.025em;color:inherit;font-synthesis:none}
.alfred-surface{font-family:var(--alfred-font-body);font-size:1rem;font-weight:400;line-height:1.5;background:var(--alfred-paper);color:var(--alfred-ink);font-synthesis:none}
.alfred-surface :where(h1,h2,h3,h4,p){margin:0}
.alfred-surface .alfred-display{font-family:var(--alfred-font-display);font-weight:400;line-height:1.04;letter-spacing:-.04em}
.alfred-surface .alfred-label{font-family:var(--alfred-font-mono);font-size:.75rem;line-height:1.333333;letter-spacing:.04em;text-transform:uppercase}
.alfred-panel{border:2px solid var(--alfred-ink);border-radius:1.25rem;background:var(--alfred-paper);color:var(--alfred-ink)}
'''
 for name,role in t['typography'].items():
  size=rem(role['sizePx'])
  if 'maxSizePx' in role:size=f'clamp({size},{role["fluid"]},{rem(role["maxSizePx"])})'
  css+=f'.alfred-type-{name}'+'{'+f'font-family:var(--alfred-font-{role["font"]});font-size:{size};font-weight:{role["weight"]};line-height:{role["lineHeight"]};letter-spacing:{role["trackingEm"]}em;font-synthesis:none;'+('font-variant-numeric:tabular-nums;' if role.get('tabular') else '')+'}\n'
 css+='''.alfred-stack{display:flex;flex-direction:column;gap:var(--alfred-gap-component)}
.alfred-card-layout{container-type:inline-size;container-name:alfred-card;display:flex;flex-direction:column;gap:var(--alfred-gap-field-group);padding:var(--alfred-gap-card-padding);min-width:0}
.alfred-actions{display:flex;gap:var(--alfred-gap-actions);align-items:stretch}
.alfred-actions>*{flex:1;min-width:0}
.alfred-control{box-sizing:border-box;min-height:2.75rem;padding:.5rem .75rem;border:2px solid var(--alfred-ink);border-radius:.75rem;font-family:var(--alfred-font-body);font-size:1rem;font-weight:600;line-height:1.5;color:var(--alfred-ink);background:var(--alfred-white);white-space:normal;overflow-wrap:anywhere}
.alfred-control--primary{background:var(--alfred-pink);box-shadow:4px 4px 0 var(--alfred-ink)}
.alfred-input{box-sizing:border-box;width:100%;min-height:2.75rem;padding:.5rem .75rem;border:2px solid var(--alfred-ink);border-radius:.75rem;font-family:var(--alfred-font-body);font-size:1rem;font-weight:400;line-height:1.5;background:var(--alfred-white);color:var(--alfred-ink)}
.alfred-surface :is(button,a,input,textarea,select,[role=tab]):focus-visible{outline:3px solid var(--alfred-blue);outline-offset:3px}
@media(min-width:768px){.alfred-card-layout{padding:var(--alfred-gap-card-padding-wide)}}
@media(max-width:479px){.alfred-actions{flex-direction:column}}
'''
 fonts=f'/* Alfred v{v}. Paths are relative to this stylesheet. */\n'
 for face in t['font'].values():fonts+='@font-face{font-family:"'+face['family']+'";font-style:normal;font-weight:'+face['declaredWeight']+';font-display:swap;src:url("'+face['file']+'") format("truetype")}\n'
 # Product geometry and type defaults come from the same canonical JSON.
 w=t['web']
 css=css.replace('border:2px solid',f"border:{w['borderPx']}px solid").replace('border-radius:1.25rem',f"border-radius:{rem(w['panelRadiusPx'])}").replace('border-radius:.75rem',f"border-radius:{rem(w['controlRadiusPx'])}")
 css=css.replace('min-height:2.75rem',f"min-height:{rem(w['controlMinPx'])}").replace('padding:.5rem .75rem',f"padding:{rem(w['controlPaddingBlockPx'])} {rem(w['controlPaddingInlinePx'])}")
 css=css.replace('box-shadow:4px 4px',f"box-shadow:{w['hardShadowPx']}px {w['hardShadowPx']}px").replace('outline:3px solid',f"outline:{w['focusWidthPx']}px solid").replace('outline-offset:3px',f"outline-offset:{w['focusOffsetPx']}px")
 css=css.replace('min-width:768px',f"min-width:{w['wideBreakpointPx']}px").replace('max-width:479px',f"max-width:{w['actionsStackMaxPx']}px")
 css+='@container alfred-card (max-width:'+rem(w['actionsContainerMaxPx'])+'){.alfred-actions{flex-direction:column}}\n'
 def properties(role,inline=False):
  size=rem(role['sizePx'])
  if 'maxSizePx' in role:size=f'clamp({size},{role["fluid"]},{rem(role["maxSizePx"])})'
  family='"'+t['font'][role['font']]['family']+'",'+('monospace' if role['font']=='mono' else 'sans-serif')
  return f"font-family:{family};font-size:{size};font-weight:{role['weight']};line-height:{role['lineHeight']};letter-spacing:{role['trackingEm']}em;font-synthesis:none;"+('font-variant-numeric:tabular-nums;' if role.get('tabular') else '')
 for name in ['control','input','surface']:
  selector='.alfred-'+name
  start=css.index(selector+'{');end=css.index('}',start)
  block=css[start:end]
  # Keep geometry, replace the complete role so controls follow type-token edits.
  import re
  block=re.sub(r'font-family:[^;]+;font-size:[^;]+;font-weight:[^;]+;line-height:[^;]+;',properties(t['typography']['body' if name=='surface' else name]),block)
  css=css[:start]+block+css[end:]
 bridge=BRIDGE
 bridge=bridge.replace('--radius-lg: .75rem;',f"--radius-lg: {rem(w['controlRadiusPx'])};").replace('--radius-xl: 1.25rem;',f"--radius-xl: {rem(w['panelRadiusPx'])};")
 for name,role in t['typography'].items():bridge+='@utility type-'+name+' {'+properties(role)+'}\n'
 return {'tokens.css':css,'fonts.css':fonts,'shadcn-v4.css':bridge}
if __name__=='__main__':
 for name,content in generate().items():(ROOT/'assets'/name).write_text(content)
 print('Generated tokens.css, fonts.css and shadcn-v4.css from tokens.json')
